<content>
1: # Introduction
2: 
3: zip.js is a JavaScript open-source library (BSD-3-Clause license) for
4: compressing and decompressing zip files. It has been designed to handle large amounts
5: of data. It supports notably multi-core compression, native compression with
6: compression streams, archives larger than 4GB with Zip64, split zip files, data
7: encryption, and Deflate64 decompression.
8: 
9: # Demo
10: 
11: See https://gildas-lormeau.github.io/zip-manager
12: 
13: # Documentation
14: 
15: See here for more info: https://gildas-lormeau.github.io/zip.js/
16: 
17: # Examples
18: 
19: ## Hello world
20: 
21: ```js
22: import {
23:   BlobReader,
24:   BlobWriter,
25:   TextReader,
26:   TextWriter,
27:   ZipReader,
28:   ZipWriter
29: } from "@zip.js/zip.js";
30: // "jsr:@zip-js/zip-js" for Deno
31: 
32: // ----
33: // Write the zip file
34: // ----
35: 
36: // Creates a BlobWriter object where the zip content will be written.
37: const zipFileWriter = new BlobWriter();
38: // Creates a TextReader object storing the text of the entry to add in the zip
39: // (i.e. "Hello world!").
40: const helloWorldReader = new TextReader("Hello world!");
41: 
42: // Creates a ZipWriter object writing data via `zipFileWriter`, adds the entry
43: // "hello.txt" containing the text "Hello world!" via `helloWorldReader`, and
44: // closes the writer.
45: const zipWriter = new ZipWriter(zipFileWriter);
46: await zipWriter.add("hello.txt", helloWorldReader);
47: await zipWriter.close();
48: 
49: // Retrieves the Blob object containing the zip content into `zipFileBlob`. It
50: // is also returned by zipWriter.close() for more convenience.
51: const zipFileBlob = await zipFileWriter.getData();
52: 
53: // ----
54: // Read the zip file
55: // ----
56: 
57: // Creates a BlobReader object used to read `zipFileBlob`.
58: const zipFileReader = new BlobReader(zipFileBlob);
59: // Creates a TextWriter object where the content of the first entry in the zip
60: // will be written.
61: const helloWorldWriter = new TextWriter();
62: 
63: // Creates a ZipReader object reading the zip content via `zipFileReader`,
64: // retrieves metadata (name, dates, etc.) of the first entry, retrieves its
65: // content via `helloWorldWriter`, and closes the reader.
66: const zipReader = new ZipReader(zipFileReader);
67: const firstEntry = (await zipReader.getEntries()).shift();
68: const helloWorldText = await firstEntry.getData(helloWorldWriter);
69: await zipReader.close();
70: 
71: // Displays "Hello world!".
72: console.log(helloWorldText);
73: ```
74: 
75: Run the code on JSFiddle: https://jsfiddle.net/tm9fhvab/
76: 
77: ## Hello world with Streams
78: 
79: ```js
80: import {
81:   BlobReader,
82:   ZipReader,
83:   ZipWriter
84: } from "@zip-js/zip-js";
85: // Prefix "@zip-js/zip-js" with "jsr:" for Deno
86: 
87: // ----
88: // Write the zip file
89: // ----
90: 
91: // Creates a TransformStream object, the zip content will be written in the
92: // `writable` property.
93: const zipFileStream = new TransformStream();
94: // Creates a Promise object resolved to the zip content returned as a Blob
95: // object retrieved from `zipFileStream.readable`.
96: const zipFileBlobPromise = new Response(zipFileStream.readable).blob();
97: // Creates a ReadableStream object storing the text of the entry to add in the
98: // zip (i.e. "Hello world!").
99: const helloWorldReadable = new Blob(["Hello world!"]).stream();
100: 
101: // Creates a ZipWriter object writing data into `zipFileStream.writable`, adds
102: // the entry "hello.txt" containing the text "Hello world!" retrieved from
103: // `helloWorldReadable`, and closes the writer.
104: const zipWriter = new ZipWriter(zipFileStream.writable);
105: await zipWriter.add("hello.txt", helloWorldReadable);
106: await zipWriter.close();
107: 
108: // Retrieves the Blob object containing the zip content into `zipFileBlob`.
109: const zipFileBlob = await zipFileBlobPromise;
110: 
111: // ----
112: // Read the zip file
113: // ----
114: 
115: // Creates a BlobReader object used to read `zipFileBlob`.
116: const zipFileReader = new BlobReader(zipFileBlob);
117: // Creates a TransformStream object, the content of the first entry in the zip
118: // will be written in the `writable` property.
119: const helloWorldStream = new TransformStream();
120: // Creates a Promise object resolved to the content of the first entry returned
121: // as text from `helloWorldStream.readable`.
122: const helloWorldTextPromise = new Response(helloWorldStream.readable).text();
123: 
124: // Creates a ZipReader object reading the zip content via `zipFileReader`,
125: // retrieves metadata (name, dates, etc.) of the first entry, retrieves its
126: // content into `helloWorldStream.writable`, and closes the reader.
127: const zipReader = new ZipReader(zipFileReader);
128: const firstEntry = (await zipReader.getEntries()).shift();
129: await firstEntry.getData(helloWorldStream.writable);
130: await zipReader.close();
131: 
132: // Displays "Hello world!".
133: const helloWorldText = await helloWorldTextPromise;
134: console.log(helloWorldText);
135: ```
136: 
137: Run the code on JSFiddle: https://jsfiddle.net/aw3d6f4o/
138: 
139: ## Adding concurrently multiple entries in a zip file
140: 
141: ```js
142: import {
143:   BlobWriter,
144:   HttpReader,
145:   TextReader,
146:   ZipWriter,
147: } from "@zip-js/zip-js";
148: // Prefix "@zip-js/zip-js" with "jsr:" for Deno
149: 
150: const README_URL = "https://unpkg.com/@zip.js/zip.js/README.md";
151: getZipFileBlob()
152:   .then(downloadFile);
153: 
154: async function getZipFileBlob() {
155:   const zipWriter = new ZipWriter(new BlobWriter("application/zip"));
156:   await Promise.all([
157:     zipWriter.add("hello.txt", new TextReader("Hello world!")),
158:     zipWriter.add("README.md", new HttpReader(README_URL)),
159:   ]);
160:   return zipWriter.close();
161: }
162: 
163: function downloadFile(blob) {
164:   document.body.appendChild(Object.assign(document.createElement("a"), {
165:     download: "hello.zip",
166:     href: URL.createObjectURL(blob),
167:     textContent: "Download zip file",
168:   }));
169: }
170: ```
